insert into public.destinations (id,name,slug,description,image,hotel_count) values
('00000000-0000-0000-0000-000000000001','Madikeri','madikeri','The heart of Coorg — misty hills, historic forts, and breathtaking viewpoints.','https://images.pexels.com/photos/33046721/pexels-photo-33046721.png?auto=compress&cs=tinysrgb&h=650&w=940',4),
('00000000-0000-0000-0000-000000000002','Kushalnagar','kushalnagar','Gateway to Coorg with serene riverbanks and the famous Dubare Elephant Camp.','https://images.pexels.com/photos/14844302/pexels-photo-14844302.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',3),
('00000000-0000-0000-0000-000000000003','Virajpet','virajpet','Coffee plantations, rolling green hills, and the charming second town of Coorg.','https://images.pexels.com/photos/3848200/pexels-photo-3848200.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',2),
('00000000-0000-0000-0000-000000000004','Somwarpet','somwarpet','Peaceful landscapes, spice gardens, and authentic Coorgi village life.','https://images.pexels.com/photos/35659936/pexels-photo-35659936.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',2),
('00000000-0000-0000-0000-000000000005','Other Coorg Destinations','other-coorg','Discover hidden gems across the Coorg region — from Talacauvery to Mandalpatti.','https://images.pexels.com/photos/29890282/pexels-photo-29890282.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',3)
