insert into public.hotels (id,name,slug,location,destination_id,image,gallery,rating,review_count,star_rating,description,amenities,price_per_night,original_price,featured) values
('10000000-0000-0000-0000-000000000001','Manju Misty Heights','manju-misty-heights','Madikeri, Coorg','00000000-0000-0000-0000-000000000001','https://images.pexels.com/photos/6434592/pexels-photo-6434592.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/6434592/pexels-photo-6434592.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/8082217/pexels-photo-8082217.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/8134808/pexels-photo-8134808.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.8,342,5,'A premium hilltop retreat with panoramic views of the misty Coorg valleys.',array['wifi','parking','restaurant','room-service','breakfast','family-rooms'],4800,6200,true),
('10000000-0000-0000-0000-000000000002','Manju Coffee County','manju-coffee-county','Virajpet, Coorg','00000000-0000-0000-0000-000000000003','https://images.pexels.com/photos/2771935/pexels-photo-2771935.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/2771935/pexels-photo-2771935.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/3011575/pexels-photo-3011575.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/2259226/pexels-photo-2259226.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.7,218,4,'Nestled amidst working coffee plantations with guided estate tours.',array['wifi','parking','restaurant','breakfast','travel','housekeeping'],3600,4500,true),
('10000000-0000-0000-0000-000000000003','Manju Riverside Resort','manju-riverside-resort','Kushalnagar, Coorg','00000000-0000-0000-0000-000000000002','https://images.pexels.com/photos/2259226/pexels-photo-2259226.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/2259226/pexels-photo-2259226.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/137569/pexels-photo-137569.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/1714976/pexels-photo-1714976.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.6,187,4,'Riverside luxury with nature walks, bonfire evenings, and family activities.',array['wifi','parking','restaurant','room-service','family-rooms','reception'],4200,5500,true),
('10000000-0000-0000-0000-000000000004','Manju Valley Inn','manju-valley-inn','Somwarpet, Coorg','00000000-0000-0000-0000-000000000004','https://images.pexels.com/photos/97083/pexels-photo-97083.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/97083/pexels-photo-97083.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/2736384/pexels-photo-2736384.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/24461266/pexels-photo-24461266.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.5,156,3,'Cozy valley-view rooms with authentic Coorgi cuisine and warm hospitality.',array['wifi','parking','restaurant','breakfast','housekeeping','travel'],2800,3600,true),
('10000000-0000-0000-0000-000000000005','Manju Heritage Homestay','manju-heritage-homestay','Madikeri, Coorg','00000000-0000-0000-0000-000000000001','https://images.pexels.com/photos/8082217/pexels-photo-8082217.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/8082217/pexels-photo-8082217.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/6466496/pexels-photo-6466496.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/14547139/pexels-photo-14547139.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.9,289,5,'A restored Coorgi plantation bungalow offering heritage luxury and home-cooked meals.',array['wifi','parking','restaurant','room-service','breakfast','travel','housekeeping'],5500,7000,true),
('10000000-0000-0000-0000-000000000006','Manju Green Gate Lodge','manju-green-gate-lodge','Kushalnagar, Coorg','00000000-0000-0000-0000-000000000002','https://images.pexels.com/photos/14547139/pexels-photo-14547139.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',array['https://images.pexels.com/photos/14547139/pexels-photo-14547139.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/7507131/pexels-photo-7507131.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/18651505/pexels-photo-18651505.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'],4.4,134,3,'Budget-friendly comfort near Dubare Elephant Camp with all essential amenities.',array['wifi','parking','breakfast','reception','housekeeping'],2200,null,false)
