insert into public.experiences (name,description,image,sort_order) values
('Mandalpatti','A stunning mountain peak offering 360-degree views of the Coorg hills.','https://images.pexels.com/photos/6189814/pexels-photo-6189814.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',1),
('Abbey Falls','A breathtaking waterfall nestled amidst coffee plantations and spice estates.','https://images.pexels.com/photos/5046379/pexels-photo-5046379.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',2),
('Raja''s Seat','A seasonal garden with spectacular sunset views over the Coorg valleys.','https://images.pexels.com/photos/2443872/pexels-photo-2443872.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',3),
('Dubare','Interact with elephants at the famous Dubare Elephant Camp on the riverbank.','https://images.pexels.com/photos/35073235/pexels-photo-35073235.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',4),
('Coffee Plantations','Walk through lush coffee estates and learn the art of Coorgi coffee-making.','https://images.pexels.com/photos/10348767/pexels-photo-10348767.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',5),
('Nagarhole','Spot wild elephants, deer, and tigers in this pristine national park.','https://images.pexels.com/photos/12414379/pexels-photo-12414379.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',6),
('Talacauvery','The sacred origin of the River Cauvery, set amidst misty Brahmagiri hills.','https://images.pexels.com/photos/19041829/pexels-photo-19041829.jpeg?auto=compress&cs=tinysrgb&h=650&w=940',7);
insert into public.features (title,description,icon,sort_order) values
('Prime Coorg Locations','Our hotels are strategically located near top attractions in Madikeri, Kushalnagar, Virajpet, and Somwarpet.','MapPin',1),
('Comfortable Rooms','Well-appointed rooms with modern amenities, plush bedding, and beautiful valley or plantation views.','BedDouble',2),
('Trusted Hospitality','Over a decade of hosting thousands of happy guests with genuine Coorgi warmth and care.','HeartHandshake',3),
('Competitive Prices','Transparent pricing with no hidden charges. Best available rates across all our properties.','BadgePercent',4),
('Family-Friendly Stays','Spacious family rooms, kid-friendly menus, and activities for all age groups.','Users',5),
('24/7 Guest Support','Round-the-clock front desk and concierge service to make your stay effortless.','Headset',6);
